4502	Status SegmentImpl::open_fts_indexers(bool create) {
4503	  if (!collection_schema_->has_fts_field()) {
4504	    return Status::OK();
4505	  }
4506	
4507	  if (create) {
4508	    auto block_id = allocate_block_id();
4509	    auto fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block_id);
4510	    fts_indexer_ = FtsIndexer::CreateAndOpen(
4511	        fts_path, collection_schema_->fts_fields(), true);
4512	    if (!fts_indexer_) {
4513	      return Status::InternalError("open_fts_indexers: create failed at [",
4514	                                   fts_path, "]");
4515	    }
4516	    segment_meta_->add_persisted_block(
4517	        BlockMeta{block_id, BlockType::FTS_INDEX, 0, 0, 0, {}});
4518	  } else {
4519	    for (const auto &block : segment_meta_->persisted_blocks()) {
4520	      if (block.type() == BlockType::FTS_INDEX) {
4521	        auto fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block.id());
4522	        fts_indexer_ = FtsIndexer::CreateAndOpen(
4523	            fts_path, collection_schema_->fts_fields(), false,
4524	            options_.read_only_);
4525	        if (!fts_indexer_) {
4526	          return Status::InternalError("open_fts_indexers: open failed at [",
4527	                                       fts_path, "]");
4528	        }
4529	        break;
4530	      }
4531	    }
4532	  }
4533	
4534	  has_fts_ = (fts_indexer_ != nullptr);
4535	  return Status::OK();
4536	}
