4552	Status SegmentImpl::insert_fts_indexer(Doc &doc) {
4553	  if (!has_fts_) {
4554	    return Status::OK();
4555	  }
4556	  for (const auto &field : collection_schema_->fts_fields()) {
4557	    auto value = doc.get<std::string>(field->name());
4558	    if (value.has_value()) {
4559	      auto segment_doc_id = doc_ids_.size();
4560	      auto s =
4561	          fts_indexer_->insert(field->name(), segment_doc_id, value.value());
4562	      if (!s.ok()) {
4563	        return s;
4564	      }
4565	    }
4566	  }
4567	  return Status::OK();
4568	}
