4603	Status SegmentImpl::create_fts_index(const std::string &column,
4604	                                     const IndexParams::Ptr &index_params,
4605	                                     SegmentMeta::Ptr *out_segment_meta,
4606	                                     FtsIndexer::Ptr *out_fts_indexer) {
4607	  auto fts_params = std::dynamic_pointer_cast<FtsIndexParams>(index_params);
4608	  if (!fts_params) {
4609	    return Status::InvalidArgument("create_fts_index: not FtsIndexParams");
4610	  }
4611	
4612	  auto field = collection_schema_->get_field(column);
4613	  if (!field) {
4614	    return Status::NotFound("create_fts_index: field not found: ", column);
4615	  }
4616	
4617	  if (field->index_params() != nullptr) {
4618	    if (*field->index_params() == *index_params) {
4619	      // Already indexed with same params, nothing to do.
4620	      *out_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
4621	      *out_fts_indexer = fts_indexer_;
4622	      return Status::OK();
4623	    }
4624	    if (field->index_params()->type() != index_params->type()) {
4625	      return Status::InvalidArgument(
4626	          "create_fts_index: field[", column, "] already has index type ",
4627	          IndexTypeCodeBook::AsString(field->index_params()->type()));
4628	    }
4629	    // Same type but different params — will rebuild below.
4630	  }
4631	
4632	  auto new_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
4633	  new_segment_meta->remove_fts_index_block();
4634	
4635	  auto block_id = allocate_block_id();
4636	  auto new_fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block_id);
4637	
4638	  // Build a new schema that includes the new FTS field for the snapshot open.
4639	  auto new_schema = std::make_shared<CollectionSchema>(*collection_schema_);
4640	  new_schema->get_field(column)->set_index_params(index_params);
4641	
4642	  FtsIndexer::Ptr new_fts_indexer;
4643	  if (fts_indexer_) {
4644	    // Snapshot existing fts DB, then open the copy with current schema.
4645	    auto s = fts_indexer_->create_snapshot(new_fts_path);
4646	    CHECK_RETURN_STATUS(s);
4647	
4648	    new_fts_indexer = FtsIndexer::CreateAndOpen(
4649	        new_fts_path, collection_schema_->fts_fields(), false);
4650	  } else {
4651	    // No existing fts DB — create a fresh one.
4652	    new_fts_indexer =
4653	        FtsIndexer::CreateAndOpen(new_fts_path, new_schema->fts_fields(), true);
4654	  }
4655	  if (!new_fts_indexer) {
4656	    FileHelper::RemoveDirectory(new_fts_path);
4657	    return Status::InternalError("create_fts_index: failed to open snapshot");
4658	  }
4659	
4660	  // If the field already exists in the snapshot (params change), remove it
4661	  // first so we can recreate with the new params.
4662	  if (new_fts_indexer->has_field(column)) {
4663	    auto s = new_fts_indexer->remove_field_indexer(column);
4664	    if (!s.ok()) {
4665	      FileHelper::RemoveDirectory(new_fts_path);
4666	      return s;
4667	    }
4668	  }
4669	
4670	  {
4671	    auto new_field_schema = std::make_shared<FieldSchema>(
4672	        column, field->data_type(), field->nullable(), index_params);
4673	    auto s = new_fts_indexer->create_field_indexer(*new_field_schema);
4674	    if (!s.ok()) {
4675	      FileHelper::RemoveDirectory(new_fts_path);
4676	      return s;
4677	    }
4678	  }
4679	
4680	  // Scan forward store and replay all existing documents.
4681	  auto reader = scan({column});
4682	  if (reader) {
4683	    uint32_t seg_doc_id = 0;
4684	    while (true) {
4685	      auto batch = reader->Next();
4686	      if (!batch.ok()) {
4687	        FileHelper::RemoveDirectory(new_fts_path);
4688	        return Status::InternalError("create_fts_index: scan failed: ",
4689	                                     batch.status().message());
4690	      }
4691	      auto batch_value = batch.ValueOrDie();
4692	      if (!batch_value) {
4693	        break;
4694	      }
4695	      auto col_idx = batch_value->schema()->GetFieldIndex(column);
4696	      if (col_idx < 0) {
4697	        seg_doc_id += batch_value->num_rows();
4698	        continue;
4699	      }
4700	      auto string_array = std::static_pointer_cast<arrow::StringArray>(
4701	          batch_value->column(col_idx));
4702	      for (int64_t i = 0; i < string_array->length(); ++i) {
4703	        if (!string_array->IsNull(i)) {
4704	          auto s = new_fts_indexer->insert(column, seg_doc_id,
4705	                                           string_array->GetString(i));
4706	          if (!s.ok()) {
4707	            FileHelper::RemoveDirectory(new_fts_path);
4708	            return s;
4709	          }
4710	        }
4711	        seg_doc_id++;
4712	      }
4713	    }
4714	  }
4715	
4716	  // Seal the new field (flush + convert to BitPacked + drop side CFs).
4717	  auto s = new_fts_indexer->seal(column);
4718	  if (!s.ok()) {
4719	    FileHelper::RemoveDirectory(new_fts_path);
4720	    return s;
4721	  }
4722	
4723	  s = new_fts_indexer->flush();
4724	  if (!s.ok()) {
4725	    FileHelper::RemoveDirectory(new_fts_path);
4726	    return s;
4727	  }
4728	
4729	  // Register the new block in segment meta.
4730	  BlockMeta block;
4731	  block.set_id(block_id);
4732	  block.set_type(BlockType::FTS_INDEX);
4733	  new_segment_meta->add_persisted_block(block);
4734	
4735	  *out_segment_meta = new_segment_meta;
4736	  *out_fts_indexer = new_fts_indexer;
4737	
4738	  return Status::OK();
4739	}
