4741	Status SegmentImpl::drop_fts_index(const std::string &column,
4742	                                   SegmentMeta::Ptr *out_segment_meta,
4743	                                   FtsIndexer::Ptr *out_fts_indexer) {
4744	  auto field = collection_schema_->get_field(column);
4745	  if (!field) {
4746	    return Status::NotFound("drop_fts_index: field not found: ", column);
4747	  }
4748	
4749	  auto new_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
4750	  new_segment_meta->remove_fts_index_block();
4751	
4752	  // Build a new schema without the FTS index on this column.
4753	  auto new_schema = std::make_shared<CollectionSchema>(*collection_schema_);
4754	  new_schema->get_field(column)->set_index_params(nullptr);
4755	
4756	  if (!fts_indexer_) {
4757	    *out_segment_meta = new_segment_meta;
4758	    *out_fts_indexer = nullptr;
4759	    return Status::OK();
4760	  }
4761	
4762	  // Check if other FTS fields remain after removal.
4763	  bool has_other_fts = new_schema->has_fts_field();
4764	
4765	  if (has_other_fts) {
4766	    auto block_id = allocate_block_id();
4767	    auto new_fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block_id);
4768	
4769	    // Snapshot and reopen without this field.
4770	    auto s = fts_indexer_->create_snapshot(new_fts_path);
4771	    CHECK_RETURN_STATUS(s);
4772	
4773	    auto new_fts_indexer = FtsIndexer::CreateAndOpen(
4774	        new_fts_path, collection_schema_->fts_fields(), false);
4775	    if (!new_fts_indexer) {
4776	      FileHelper::RemoveDirectory(new_fts_path);
4777	      return Status::InternalError("drop_fts_index: failed to open snapshot");
4778	    }
4779	
4780	    s = new_fts_indexer->remove_field_indexer(column);
4781	    CHECK_RETURN_STATUS(s);
4782	
4783	    s = new_fts_indexer->flush();
4784	    CHECK_RETURN_STATUS(s);
4785	
4786	    BlockMeta block;
4787	    block.set_id(block_id);
4788	    block.set_type(BlockType::FTS_INDEX);
4789	    new_segment_meta->add_persisted_block(block);
4790	
4791	    *out_fts_indexer = new_fts_indexer;
4792	  } else {
4793	    // Last FTS field removed — no new indexer.
4794	    *out_fts_indexer = nullptr;
4795	  }
4796	
4797	  *out_segment_meta = new_segment_meta;
4798	  return Status::OK();
4799	}
