4801	Status SegmentImpl::reload_fts_index(const CollectionSchema &schema,
4802	                                     const SegmentMeta::Ptr &segment_meta,
4803	                                     const FtsIndexer::Ptr &new_fts_indexer) {
4804	  collection_schema_ = std::make_shared<CollectionSchema>(schema);
4805	  segment_meta_ = segment_meta;
4806	
4807	  if (fts_indexer_) {
4808	    auto old_dir = fts_indexer_->working_dir();
4809	    fts_indexer_ = new_fts_indexer;
4810	    FileHelper::RemoveDirectory(old_dir);
4811	  } else {
4812	    fts_indexer_ = new_fts_indexer;
4813	  }
4814	
4815	  has_fts_ = (fts_indexer_ != nullptr);
4816	  fresh_persist_block_offset();
4817	
4818	  return Status::OK();
4819	}
